\begin{equation}\label{probl1}
\underset{\x\in\bcX}{\min} f(\x), \qquad\mbox{with}\quad f(\x)=\Esp_{\ubar{\theta}}\left[f_{\ubar{\theta}}(\x)\right],
\end{equation}

where {\bl the nonempty set} $\bcX \subseteq\rn$ {\bl of nonzero measure} is a feasible region; the values of the function $f:\rn\to\R$ are available only through $f_{\ubar{\theta}}$, a stochastically noisy version of $f$;  ${\ubar{\theta}}$ is a random variable whose probability distribution is possibly unknown; and $\Esp_{\ubar{\theta}}$ denotes the {\it expectation} with respect to ${\ubar{\theta}}$. Problem~\eqref{probl1} arises, for example, in statistical machine learning~\cite{bottou2018optimization} where $\ubar{\theta}$ is a random variable describing a given sample set while $f_{\ubar{\theta}}$ represents the composition of a loss function and a prediction function. {\bl We particularly target settings where the problem dimension $n>100$, which is large in the context of derivative-free methods for stochastic optimization.}


Throughout the manuscript, vectors are written in lowercase boldface (e.g., $\vb\in\rn, n\geq 2$), and matrices are written in uppercase boldface (e.g., $\Ub\in\rnp$). Unless otherwise stated, all random quantities are underlined (e.g., $\ubar{z}$, $\vrandom$, $\Urandom$) and are defined on the same probability space $(\Omega,\F,\pr)$. The nonempty set~$\Omega$ referred to as the {\it sample space} is a collection of elements~$\omega$ called {\it sample points}, while subsets of~$\Omega$ are called {\it events}. The collection, $\F$, of these events is called a $\sigma$-algebra; and the finite measure~$\pr$ defined on the {\it measurable space} $(\Omega,\F)$, with $\prob{\Omega}=1$, is a {\it probability measure}. A {\it filtration} is an increasing subsequence $\accolade{\mathcal{H}_k}_k$ of $\sigma$-algebras of~$\F$. By denoting by~$\mathscr{B}(\rn)$ the Borel $\sigma$-algebra generated by open sets of~$\rn$, a real-valued random variable~$\ubar{z}$ is a measurable map $\ubar{z}:(\Omega,\F,\pr)\to (\R,\mathscr{B}(\R))$, where measurability means that $\accolade{\ubar{z}\in \mathscr{E}}:=\accolade{\omega\in\Omega:\ubar{z}(\omega)\in\mathscr{E}}=:\ubar{z}^{-1}(\mathscr{E})\in\F$ for all $\mathscr{E}\in \mathscr{B}(\R)$~\cite{bhattacharya2007basic}. A real-valued random matrix is a matrix-valued random variable, that is, a matrix whose entries are real-valued random variables. $\normii{\ub}:=\left(\sum_{i=1}^n u_i^2\right)^{1/2}$ denotes the Euclidean norm of a vector $\ub:=(u_1,\dots,u_n)^{\top}\in\rn$.  $\norme{\cdot}$ is used for the norm of a matrix and is assumed 
%GAIL - bu "supposed to be" do you mean that it really is not? or do you mean it is assumed to be?
to be {\it consistent} with the Euclidean norm, that is, $\normii{\Q\ub}\leq \norme{\Q}\normii{\ub}$, which holds for both spectral and Frobenius matrix norms. $\ub^{\top}\vb=\scal{\ub}{\vb}:=\sum_{i=1}^n u_i v_i$ denotes the {\it scalar product} or {\it dot product} of the vectors $\ub$ and $\vb:=(v_1,\dots,v_n)^{\top}\in\rn$. $K_{\infty}$ denotes the random set of all {\it unsuccessful iterations} of a given algorithm. A realization of a random set~$K$ is denoted by~$\mathcal{K}$; that is, $K(\omega)=\mathcal{K}$ for some~$\omega\in\Omega$. {\bl For $a\leq b$, $\intbracket{a,b}:=[a,b]\cap\Z$ is the set of integers in the interval $[a,b]$.}


SDDS algorithms were introduced in~\cite{dzahini2020expected} to solve the stochastic optimization problem~\eqref{probl1} in the particular case $\bcX=\rn$. These algorithms use a framework inspired by that of StoMADS~\cite{audet2019stomads} and the broad class of methods presented in~\cite{Vicente2013} using a {\it generating set search} method~\cite{KoLeTo03a}, such as pattern search and generalized pattern search~\cite{AuDe03a}. Each iteration of SDDS algorithms is composed of two main steps: an optional {\it search}, not shown in~\cite[Algorithm~1]{dzahini2020expected}, and not detailed in Algorithm~\ref{vagueDirAlgo} for simplicity, and the ``more disciplined''~\cite{LaMeWi2019} {\it poll} on which  the theoretical analyses rely. Broadly speaking, each poll step of an SDDS method generates a finite set of {\it poll points} by taking an {\it incumbent solution}~$\xk\in\rn$ and adding terms of the form~$\dk\di^n$, where $\dk>0$ is the {\it stepsize} and $\di^n\in\rn$ is a nonzero vector from a finite set $\mathbb{D}^n_k\subset\rn$ of {\it poll directions}. More precisely, $\mathbb{D}^n_k$ is a PSS, meaning that any vector in~$\rn$ can be written as a nonnegative linear combination of elements in~$\mathbb{D}^n_k$~\cite[Definition~6.1]{AuHa2017} or, equivalently, the cosine measure $\kappa(\mathbb{D}^n_k)>0$, where 
%for a given $\mathbb{D}\subset\rn$,
\begin{equation}\label{cosineMeasureDef}
\kappa(\mathbb{D}^q):=\underset{\wb\in \R^q,\wb\neq \bm{0}}{\min}\ \underset{\di^q\in \mathbb{D}^q}{\max}\frac{\scal{\wb}{\di^q}}{\normii{\wb}\normii{\di^q}}\quad\mbox{with}\quad \mathbb{D}^q\subset\R^q.
\end{equation}

\begin{equation}\label{cosineDescentDkn}
\mbox{for any}\ \vi\in\rn,\quad\exists \di_{\star}^n(\vi)\in \mathbb{D}^n\subset\rn\quad\mbox{such that}\quad \kappa(\mathbb{D}^n)\normii{\vi}\normii{\di^n_{\star}(\vi)}\leq \scal{\vi}{\di^n_{\star}(\vi)}.
\end{equation}

\begin{definition}\label{wellAlignment}
For fixed $\alpha_Q,\beta_Q\in (0,1/2)$, 
%a sequence $\accoladekinN{\QkRandom}$ of independent 
a random matrix $\Qrandom\in\rnp$ is called $(1-\beta_Q)$-probabilistically $\alpha_Q$-well aligned if, for all $\vb\in\rn$, $\prob{\normii{\Qrandom^{\top}\vb}\geq \alpha_Q\normii{\vb}}\geq 1-\beta_Q$. Such matrices are referred to as $WAM(\alpha_Q,\beta_Q)$.
\end{definition}

\begin{assumption}\label{JltAss1}{\bl (Inspired by~\cite[Assumptions~2 and~3]{DzaWildSub2022} and~\cite{CRsubspace2021})}
The random matrix $\Qrandom\in\rnp$ is a $WAM(\alpha_Q,\beta_Q)$ for fixed $\alpha_Q,\beta_Q\in (0,1/2)$ and satisfies $\norme{\Qrandom}\leq\Qmax$ almost surely for some $\Qmax>0$. 
%and $\prob{\normii{\QrandomTranspose\bm{v}}\geq \alpha_Q\normii{\bm{v}}}\geq 1-\beta_Q$ for all $\bm{v}\in\rn$, for some $\alpha_Q\in (0,1)$ and $\beta_Q\in (0,1/2)$.
\end{assumption}

The poll directions used by Algorithm~\ref{algoStoDARS} are generated by using Haar-distributed orthogonal random matrices. Recall that a matrix $\bm{O}\in \rnn$ is {\it orthogonal} if and only if $\bm{O}^{\top}\bm{O}=\bm{O}\bm{O}^{\top}=\bm{I}_n$ or equivalently if its columns form an orthonormal basis of $\rn$~\cite[Section~1.1]{MeckesElizHaar2019}. Throughout the manuscript, the compact Lie group of $n\times n$ orthogonal matrices over~$\R$ will be denoted by $\mathbb{O}(n)$. 
%We also recall that $\mathbb{O}(n)$ is a group under multiplication, and that this group admits a compact Lie group structure, that is, it is also a differentiable manifold such that the multiplication operation $(\bm{A}, \bm{B})\mapsto \bm{A}\bm{B}$ and the inversion operation $\bm{A}\mapsto \bm{A}^{-1}$ are smooth maps. 
A {\it uniform random element} of $\mathbb{O}(n)$ is a random $\Urandom\in \mathbb{O}(n)$ whose distribution is translation invariant; that is, for any fixed $\bm{O}\in \mathbb{O}(n)$, $\bm{O}\Urandom\equald \Urandom\bm{O}\equald \Urandom$~\cite[Section~1.2]{MeckesElizHaar2019}, where ``$\equald$'' is used for the equality in distribution. In particular, there exists a unique translation-invariant probability measure on $\mathbb{O}(n)$ called Haar measure on~$\mathbb{O}(n)$~\cite[Theorem~1.4]{MeckesElizHaar2019}. Any random matrix whose distribution is Haar measure will be called Haar-{\it distributed matrix}. 


\begin{definition}\label{epsAccDef0}
Given $\ef>0$, $\xk\in\rn$, and $\ub:=\Ukp\di^p=\sqrt{\frac{p}{n}}\Qk\di^p\in\rn$ with $\di^p\in\pollD_k$, $\fok$ and $\fuk$ are called $\ef$-accurate estimates of $f(\xk)$ and $f(\xk+\dk\ub)$, respectively, for a given $\dk$ if
\begin{equation}\label{epsAccDef1}
\abs{\fok-f(\xk)}\leq \ef\dk^2\qquad \mbox{and}\qquad \abs{\fuk-f(\xk+\dk\ub)}\leq \ef\dk^2.
\end{equation}
\end{definition}

