\begin{proposition}\label{propKappaD1}
Assume that $\Qrandom\in\rnp$ satisfies Assumption~\ref{JltAss1}, and let $\pollD\subset \rp$ be a PSS. For any $\bm{v}\in \rn$, 
%there exists a direction $\di_{\star}\in\pollD$ such that 
\begin{equation}\label{kdprob1}
\prob{\accolade{\exists\ubar{\di}_{\star}^p\in\pollD:\frac{\alpha_Q}{\Qmax}\kappa(\pollD)\normii{\bm{v}}\normii{\Qrandom\ubar{\di}_{\star}^p}\leq \scal{\bm{v}}{\Qrandom\ubar{\di}_{\star}^p}}}\geq 1-\beta_Q.
\end{equation}
In other words, with high probability, there always exists a random direction $\Qrandom\ubar{\di}_{\star}^p\in\accolade{\Qrandom\di^p:\di^p\in\pollD}\subset\rn$ that makes an acute angle with $\bm{v}$. The same result holds in the case of a random PSS $\pollDrandom\subset\rp$; that is,
\begin{equation}\label{kdprob1prime}
\prob{\accolade{\exists\ubar{\di}_{\star}^p\in\pollDrandom:\frac{\alpha_Q}{\Qmax}\kappa(\pollDrandom)\normii{\bm{v}}\normii{\Qrandom\ubar{\di}_{\star}^p}\leq \scal{\bm{v}}{\Qrandom\ubar{\di}_{\star}^p}}}\geq 1-\beta_Q.
\end{equation}
\end{proposition}

\begin{proof}
Let $\bm{v}\in \rn$ be given. Assume that the event $\mathscr{E}_1:=\accolade{\normii{\QrandomTranspose\bm{v}}\geq \alpha_Q\normii{\bm{v}}}$ occurs, which happens with a probability of at least $1-\beta_Q$, and let $\omega\in\mathscr{E}_1$ be arbitrary. Since $\pollD$ is a PSS, it contains a direction $\di_{\star}^p=\ubar{\di}_{\star}^p(\omega)$ that makes an acute angle with the deterministic vector $\Qrandom(\omega)^\top \bm{v}\in \rp$. Formally thanks to~\eqref{cosineDescentDkn}, this means that 
\begin{equation}\label{kdeq1}
\kappa(\pollD)\normii{\Qrandom(\omega)^\top \bm{v}}\normii{\di_{\star}^p}\leq \scal{\Qrandom(\omega)^\top \bm{v}}{\di_{\star}^p}=\scal{\bm{v}}{\Qrandom(\omega)\di_{\star}^p}.
\end{equation}
It follows from~\eqref{kdeq1} and the inequality $\normii{\Qrandom(\omega)^\top\bm{v}}\geq \alpha_Q\normii{\bm{v}}$ that $\alpha_Q\kappa(\pollD)\normii{\bm{v}}\normii{\di_{\star}^p}\leq \scal{\bm{v}}{\Qrandom(\omega)\di_{\star}^p}$, which leads to $\frac{\alpha_Q}{\Qmax}\kappa(\pollD)\normii{\bm{v}}\normii{\Qrandom(\omega)\di_{\star}^p}\leq \scal{\bm{v}}{\Qrandom(\omega)\di_{\star}^p}$, given that $\normii{\Qrandom(\omega)\di_{\star}^p}\leq \Qmax\normii{\di_{\star}^p}$. We have therefore proved that $\mathscr{E}_1\subseteq\mathscr{E}_2:=\accolade{\exists\ubar{\di}_{\star}^p\in\pollD:\frac{\alpha_Q}{\Qmax}\kappa(\pollD)\normii{\bm{v}}\normii{\Qrandom\ubar{\di}_{\star}^p}\leq \scal{\bm{v}}{\Qrandom\ubar{\di}_{\star}^p}}$, whence $\prob{\mathscr{E}_2}\geq \prob{\mathscr{E}_1}\geq 1-\beta_Q$, leading to~\eqref{kdprob1}. 

In the case of a random PSS $\pollDrandom$, the same reasoning  applies with $\pollD$ and $\di_{\star}^p$ replaced with $\pollDrandom(\omega)$ and $\di_{\star}^p(\omega)$ (which are deterministic), respectively, thus leading to~\eqref{kdprob1prime}, and the proof is completed.
\end{proof}

\begin{lemma}\label{HaarLemma}\cite[Section~2.1]{MeckesElizHaar2019}
Let $\Urandom:=(\UrandomScal_{ij})_{1\leq i,j\leq n}\in \mathbb{O}(n)$ be \emph{Haar}-distributed. Then, the entries of $\Urandom$ are identically distributed. Moreover, $\E{\UrandomScal_{11}}=0$ and $\E{\UrandomScal_{11}^2}=\frac{1}{n}$.
\end{lemma}

\begin{theorem}\label{LeviTheorem}(\cite[Theorem~5.1.4 and Exercise~5.1.12]{vershynin2018HDP})
Let $F$ be an $L_F$-Lipschitz function on the unit sphere $\mathbb{S}^{n-1}$, and let $\xiRandomVec\sim \mathcal{U}(\mathbb{S}^{n-1})$. Then there exists an absolute constant $\eta>0$ such that for every $t\geq 0$
\[\prob{\abs{F\left(\xiRandomVec\right)-\E{F\left(\xiRandomVec\right)}}\geq t}\leq 2\exp{\left(-\frac{\eta n t^2}{L_F^2}\right)}. \]
\end{theorem}

\begin{theorem}\label{JLforHaarTheor}(Inspired by~\cite[Lemma~6.1]{MeckesElizHaar2019})
Let $\varepsilon_Q, \beta_Q\in (0,1)$ and $\Urandom:=(\UrandomScal_{ij})_{1\leq i,j\leq n}\in \mathbb{O}(n)$ be a \emph{Haar}-distributed random matrix. Let $\Urandom_{p\times n}\in \rpn$ be the matrix consisting of the first $p$ rows of $\Urandom$, and define $\QrandomTranspose:=\sqrt{\frac{n}{p}}\Urandom_{p\times n}$. There exists an absolute constant $\eta>0$ such that if $p\geq  \frac{4}{\eta}\varepsilon_Q^{-2}\log\left(\frac{2}{\beta_Q}\right)$, then
\begin{equation}\label{JLTEquat}
\prob{(1-\varepsilon_Q)\normii{\x}\leq \normii{\QrandomTranspose\x}\leq(1+\varepsilon_Q)\normii{\x}}\geq 1-\beta_Q\quad\mbox{for all}\ \x\in \rn.
\end{equation} 
\end{theorem}

\begin{proof}
{\bbl See Appendix~\ref{theor22}.}
\end{proof}

\begin{lemma}\label{lemKappaD3}
Let $\Qrandom\in\rnp$ be given by Theorem~\ref{JLforHaarTheor}, and let $\pollD\subset \rp$ be a PSS. For any $\bm{v}\in \rn$, the random vector $\hat{\di}^p(\vb,\qrandom)\in\argmax\accolade{\scal{\vb}{\Qrandom\di^p}:\di^p\in\pollD}$ satisfies
%there exists a direction $\di^p_{\star}\in\pollD$ such that 
\begin{equation}\label{kdpr1}
\prob{\alpha_Q\kappa(\pollD)\normii{\bm{v}}\leq \langle\vb, \Qrandom\hat{\di}^p(\vb,\qrandom)\rangle}\geq 1-\beta_Q.
\end{equation}
A similar result holds for any $\bm{v}\in \rn$ with ${\hat{\di}^p}(\vb,\qrandom,\drandom)\in\argmax\accolade{\scal{\vb}{\Qrandom\ubar{\di}^p}:\ubar{\di}^p\in\pollDrandom}$ in the case of a random PSS $\pollDrandom\subset\rp$; that is,
\begin{equation}\label{kdpr2}
\prob{\alpha_Q\kappa(\pollDrandom)\normii{\bm{v}}\leq \langle\vb, \Qrandom{\hat{\di}^p}(\vb,\qrandom,\drandom)\rangle}\geq 1-\beta_Q.
\end{equation}
\end{lemma}

\begin{proof}
By construction, $\Q=\sqrt{\frac{n}{p}}\Ub_{\ntp}$, where $\ubar{\Ub}_{\ntp}$ represents the first $p$ columns of a Haar-distributed orthogonal matrix and $\normii{\di^p}=1$ for all $\di^p\in\pollD$, whence $\norme{\Q}=\sqrt{\frac{n}{p}}=:\Qmax =\normii{\Q\di^p}$ since $\normii{\Ub_{\ntp}\di^p}=1$. Consequently, $\accolade{\exists\ubar{\di}_{\star}^p\in\pollD:\frac{\alpha_Q}{\Qmax}\kappa(\pollD)\normii{\bm{v}}\normii{\Qrandom\ubar{\di}_{\star}^p}\leq \scal{\bm{v}}{\Qrandom\ubar{\di}_{\star}^p}}=\accolade{\exists\ubar{\di}_{\star}^p\in\pollD:\alpha_Q\kappa(\pollD)\normii{\bm{v}}\leq \scal{\bm{v}}{\Qrandom\ubar{\di}_{\star}^p}}$, which is included in the event $\accolade{\alpha_Q\kappa(\pollD)\normii{\bm{v}}\leq \langle\vb, \Qrandom{\hat{\di}^p}(\vb,\qrandom)\rangle}$, leading to~\eqref{kdpr1} thanks to~\eqref{kdprob1}. The result in~\eqref{kdpr2} follows from~\eqref{kdprob1prime} using similar arguments by replacing $\pollD$ with~$\pollDrandom$ and ${\hat{\di}^p}(\vb,\qrandom)$ with ${\hat{\di}^p}(\vb,\qrandom,\drandom)$, and the proof is completed.
\end{proof}

\begin{lemma}\cite[Theorem~2.7-$(\ell)$]{bhattacharya2007basic}\label{substLemma}
Let $\ubar{\vb}$ and $\Mrandom$ be random maps into $(\mathcal{S}_1, \mathscr{S}_1)$ and $(\mathcal{S}_2, \mathscr{S}_2)$, respectively. Let $\mathcal{F}$ be a $\sigma$-algebra and $\psi$ be a measurable real-valued function on $\left(\mathcal{S}_1\times \mathcal{S}_2, \mathscr{S}_1\bigotimes\mathscr{S}_2\right)$. If $\ubar{\vb}$ is $\mathcal{F}$-measurable, $\sigma(\Mrandom)$ and $\mathcal{F}$ are independent, and $\E{\abs{\psi(\ubar{\vb},\Mrandom)}}<\infty$, then $\E{\psi(\ubar{\vb},\Mrandom)|\mathcal{F}}=\wp(\ubar{\vb})$ almost surely, where $\wp(\vb):=\E{\psi(\vb,\Mrandom)}$ for all $\vb\in\mathcal{S}_1$.
\end{lemma}

\begin{proposition}\label{propKappaD2}
Let $\mathcal{F}$ be a $\sigma$-algebra independent of a random matrix $\Qrandom\in\rnp$ given by Theorem~\ref{JLforHaarTheor}, and let $\ubar{\vb}\in \rn$ be an $\mathcal{F}$-measurable random vector. Let $\pollD\subset \rp$ be a PSS, and consider the random vector defined by $\hat{\di}^p(\ubar{\vb},\qrandom)\in\argmax\accolade{\scal{\ubar{\vb}}{\Qrandom\di^p}:\di^p\in\pollD}$. Then 
%There exists a direction $\di_{\star}^p\in\pollD$ such that 
\begin{equation}\label{kdprob2}
\prob{\left.\alpha_Q\kappa(\pollD)\normii{\ubar{\vb}} \leq \langle\ubar{\vb}, \Qrandom\hat{\di}^p(\ubar{\vb},\qrandom)\rangle \right|\F}\geq 1-\beta_Q\quad\mbox{almost surely.}
\end{equation}
A similar result holds for any $\ubar{\vb}\in \rn$ with $\hat{\di}^p(\ubar{\vb},\qrandom,\drandom)\in\argmax\accolade{\scal{\ubar{\vb}}{\Qrandom\ubar{\di}^p}:\ubar{\di}^p\in\pollDrandom}$ in the case of a random PSS $\pollDrandom\subset\rp$ with $\Drandom$ independent of $\mathcal{F}$, 
%and for a direction ${\ubar{\di}^p}_{\star}\in \pollDrandom$; 
that is,
\begin{equation}\label{kdprob2prime}
\prob{\left.\alpha_Q\kappa(\pollDrandom)\normii{\ubar{\vb}} \leq \scal{\ubar{\vb} }{\Qrandom{\hat{\di}^p}(\ubar{\vb},\qrandom,\drandom)} \right|\F}\geq 1-\beta_Q\quad\mbox{almost surely.}
\end{equation}
\end{proposition}

\begin{proof}
Let $\psi$ defined on $(\rn\times\rnp, \mathscr{B}(\rn)\bigotimes\mathscr{B}(\rnp))$ by $\psi(\ubar{\vb},\Qrandom)=\mathds{1}_{\accolade{\alpha_Q\kappa(\pollD)\normii{\ubar{\vb}} \leq \scal{\ubar{\vb}}{\Qrandom\hat{\di}^p(\ubar{\vb},\qrandom)}}}$ be a real-valued measurable function. Since $\E{\abs{\psi(\ubar{\vb},\Qrandom)}}<\infty$ trivially, it follows from Lemma~\ref{substLemma} that $\E{\psi(\ubar{\vb},\Qrandom)|\mathcal{F}}=\wp(\ubar{\vb})$ almost surely, where $\wp(\vb):=\E{\mathds{1}_{\accolade{\alpha_Q\kappa(\pollD)\normii{\vb} \leq \scal{\vb}{\qrandom\hat{\di}^p(\vb,\qrandom)}}}}=\prob{\alpha_Q\kappa(\pollD)\normii{\vb} \leq \langle\vb,\Qrandom\hat{\di}^p(\vb,\qrandom) \rangle}$ for all $\vb\in\rn$. It follows from~\eqref{kdpr1} that $\wp(\vb)\geq 1-\beta_Q$ for all $\vb\in\rn$ whence $\wp(\ubar{\vb})\geq 1-\beta_Q$ almost surely. This means that $\wp(\ubar{\vb}):=\E{\psi(\ubar{\vb},\Qrandom)|\mathcal{F}}=\prob{\left.\alpha_Q\kappa(\pollD)\normii{\ubar{\vb}} \leq \langle\ubar{\vb}, \Qrandom\hat{\di}^p(\ubar{\vb},\qrandom)\rangle \right|\F}\geq 1-\beta_Q$ almost surely, proving~\eqref{kdprob2}. To prove~\eqref{kdprob2prime}, consider the measurable real-valued function $\chi$ defined on $(\rn\times\R^{p\times (n+m)}, \mathscr{B}(\rn)\bigotimes\mathscr{B}(\R^{p\times (n+m)}))$ by $\chi\left(\ubar{\vb},\left[\Qrandom^{\top}\ \Drandom\right]\right)=\mathds{1}_{\accolade{\alpha_Q\kappa(\pollDrandom)\normii{\ubar{\vb}} \leq \scal{\ubar{\vb}}{\qrandom\hat{\di}^p(\ubar{\vb},\qrandom,\drandom)}}}$, satisfying $\E{\abs{\chi\left(\ubar{\vb},\left[\Qrandom^{\top}\ \Drandom\right]\right)}}<\infty$. $\sigma\left(\left[\Qrandom^{\top}\ \Drandom\right]\right)$ is independent of~$\F$ whence $\E{\left. \chi\left(\ubar{\vb},\left[\Qrandom^{\top}\ \Drandom\right]\right) \right|\F}=\tilde{\wp}(\ubar{\vb})$, where $\tilde{\wp}(\vb):=\prob{\alpha_Q\kappa(\pollDrandom)\normii{{\vb}} \leq \scal{{\vb}}{\Qrandom\hat{\di}^p({\vb},\qrandom,\drandom)}}$, thanks to Lemma~\ref{substLemma}. It follows from~\eqref{kdpr2} that $\tilde{\wp}(\vb)\geq 1-\beta_Q$ $\forall\vb\in\rn$, whence $\tilde{\wp}(\ubar{\vb}):=\E{\left. \chi\left(\ubar{\vb},\left[\Qrandom^{\top}\ \Drandom\right]\right) \right|\F}\geq 1-\beta_Q$ almost surely, showing~\eqref{kdprob2prime}, and the proof is completed.
\end{proof}

\begin{proposition}\label{decreaseProp1}(Inspired by~\cite[Proposition~1]{dzahini2020expected})
Let $\gamma>2$ be a constant, and let $\fok$ and $\fuk$ be $\ef$-accurate estimates of $f(\xk)$ and $f(\xk+\dk\ub)$, respectively: 
\begin{equation}\label{decreaseEqu}
\mbox{If}\quad \fuk-\fok\leq -\gamma\ef\dk^2,\qquad\mbox{then}\qquad f(\xk+\dk\ub)-f(\xk)\leq -(\gamma-2)\ef\dk^2.
\end{equation}
