\begin{theorem}\label{zerothOrdTheor}
Let Assumptions~\ref{QkHaarAssumpt},~\ref{efkfAssump} and~\ref{boundedFassumpt} hold. 
%Let $\gamma>2$ and $\nu,\tau\in (0,1)$ satisfying $\frac{\nu}{1-\nu}\geq \frac{2(\tau^{-2}-1)}{\gamma-2}$. Assume that Assumption~\ref{efkfAssump} holds with $\beta_f\in (0,1)$ satisfying  $\frac{\beta_f}{1-\beta_f}\geq \frac{4\nu}{(1-\nu)(1-\tau^2)}$. 
