\begin{equation}\label{probl1}
\underset{\x\in\bcX}{\min} f(\x), \qquad\mbox{with}\quad f(\x)=\Esp_{\ubar{\theta}}\left[f_{\ubar{\theta}}(\x)\right],
\end{equation}

SDDS algorithms were introduced in~\cite{dzahini2020expected} to solve the stochastic optimization problem~\eqref{probl1} in the particular case $\bcX=\rn$. These algorithms use a framework inspired by that of StoMADS~\cite{audet2019stomads} and the broad class of methods presented in~\cite{Vicente2013} using a {\it generating set search} method~\cite{KoLeTo03a}, such as pattern search and generalized pattern search~\cite{AuDe03a}. Each iteration of SDDS algorithms is composed of two main steps: an optional {\it search}, not shown in~\cite[Algorithm~1]{dzahini2020expected}, and not detailed in Algorithm~\ref{vagueDirAlgo} for simplicity, and the ``more disciplined''~\cite{LaMeWi2019} {\it poll} on which  the theoretical analyses rely. Broadly speaking, each poll step of an SDDS method generates a finite set of {\it poll points} by taking an {\it incumbent solution}~$\xk\in\rn$ and adding terms of the form~$\dk\di^n$, where $\dk>0$ is the {\it stepsize} and $\di^n\in\rn$ is a nonzero vector from a finite set $\mathbb{D}^n_k\subset\rn$ of {\it poll directions}. More precisely, $\mathbb{D}^n_k$ is a PSS, meaning that any vector in~$\rn$ can be written as a nonnegative linear combination of elements in~$\mathbb{D}^n_k$~\cite[Definition~6.1]{AuHa2017} or, equivalently, the cosine measure $\kappa(\mathbb{D}^n_k)>0$, where 
%for a given $\mathbb{D}\subset\rn$,
\begin{equation}\label{cosineMeasureDef}
\kappa(\mathbb{D}^q):=\underset{\wb\in \R^q,\wb\neq \bm{0}}{\min}\ \underset{\di^q\in \mathbb{D}^q}{\max}\frac{\scal{\wb}{\di^q}}{\normii{\wb}\normii{\di^q}}\quad\mbox{with}\quad \mathbb{D}^q\subset\R^q.
\end{equation}

\begin{equation}\label{cosineDescentDkn}
\mbox{for any}\ \vi\in\rn,\quad\exists \di_{\star}^n(\vi)\in \mathbb{D}^n\subset\rn\quad\mbox{such that}\quad \kappa(\mathbb{D}^n)\normii{\vi}\normii{\di^n_{\star}(\vi)}\leq \scal{\vi}{\di^n_{\star}(\vi)}.
\end{equation}

\begin{definition}\label{wellAlignment}
For fixed $\alpha_Q,\beta_Q\in (0,1/2)$, 
%a sequence $\accoladekinN{\QkRandom}$ of independent 
a random matrix $\Qrandom\in\rnp$ is called $(1-\beta_Q)$-probabilistically $\alpha_Q$-well aligned if, for all $\vb\in\rn$, $\prob{\normii{\Qrandom^{\top}\vb}\geq \alpha_Q\normii{\vb}}\geq 1-\beta_Q$. Such matrices are referred to as $WAM(\alpha_Q,\beta_Q)$.
\end{definition}

\begin{assumption}\label{JltAss1}{\bl (Inspired by~\cite[Assumptions~2 and~3]{DzaWildSub2022} and~\cite{CRsubspace2021})}
The random matrix $\Qrandom\in\rnp$ is a $WAM(\alpha_Q,\beta_Q)$ for fixed $\alpha_Q,\beta_Q\in (0,1/2)$ and satisfies $\norme{\Qrandom}\leq\Qmax$ almost surely for some $\Qmax>0$. 
%and $\prob{\normii{\QrandomTranspose\bm{v}}\geq \alpha_Q\normii{\bm{v}}}\geq 1-\beta_Q$ for all $\bm{v}\in\rn$, for some $\alpha_Q\in (0,1)$ and $\beta_Q\in (0,1/2)$.
\end{assumption}

\begin{definition}\label{epsAccDef0}
Given $\ef>0$, $\xk\in\rn$, and $\ub:=\Ukp\di^p=\sqrt{\frac{p}{n}}\Qk\di^p\in\rn$ with $\di^p\in\pollD_k$, $\fok$ and $\fuk$ are called $\ef$-accurate estimates of $f(\xk)$ and $f(\xk+\dk\ub)$, respectively, for a given $\dk$ if
\begin{equation}\label{epsAccDef1}
\abs{\fok-f(\xk)}\leq \ef\dk^2\qquad \mbox{and}\qquad \abs{\fuk-f(\xk+\dk\ub)}\leq \ef\dk^2.
\end{equation}
\end{definition}

\begin{assumption}\label{QkHaarAssumpt}{\bl (Motivated by Theorem~\ref{JLforHaarTheor})}
For all $k\geq 0$, the independent random matrices  $\Drandom_k\in\R^{p\times m}$, with $m\in {\bl \intbracket{p+1,2p}}$, and $\Ukprandom\in\rnp$ used for subspace polling in Algorithm~\ref{algoStoDARS} are such that $\pollDrandom_k\subset\spOne$, $\Urandom_k:=\left[\Urandom_{k,\ntp}\ \, \Urandom_{k,\ntnmp}\right]\in \mathbb{O}(n)$ is Haar-distributed, and $\QkRandom:=\sqrt{\frac{n}{p}}\Ukprandom$ is $WAM(\alpha_Q,\beta_Q)$ for some $\alpha_Q, \beta_Q\in(0,1/2)$.
\end{assumption}

Next, $(\QkRandom)_{ij}$, with $(i,j)\in\mathbb{I}_{\ntp}:=\intbracket{1,n}\times\intbracket{1,p}$, denote the entries of $\QkRandom$. Likewise, $(\Drandom_k)_{i'j'}$, with $(i',j')\in\mathbb{I}_{p,m}$, denote the entries of $\pollDrandom_k$. The conditioning on the past is formalized by using the filtrations $\accoladekinN{\falgebra}$ and $\accoladekinN{\fqdalgebra}$ defined by
\begin{eqnarray*}
\falgebra&:=&\sigma\left({\ubar{f}}_{\ell}({\bm{0}}), {\ubar{f}}_{\ell}(\urandom),(\Qrandom_\ell)_{ij}, (\Drandom_\ell)_{i'j'}\ \mbox{with}\ \ell\in\intbracket{0,k-1}, (i,j)\in\mathbb{I}_{\ntp}\ \mbox{and}\ (i',j')\in\mathbb{I}_{p,m}\right)\\
\fqdalgebra&:=&\sigma\left({\ubar{f}}_{\ell}({\bm{0}}), {\ubar{f}}_{\ell}(\urandom),(\Qrandom_\ell)_{ij}, (\Drandom_\ell)_{i'j'},(\QkRandom)_{ij}, (\Drandom_k)_{i'j'} \ \mbox{with}\ \ell\in\intbracket{0,k-1}, (i,j)\in\mathbb{I}_{\ntp}\ \mbox{and}\ (i',j')\in\mathbb{I}_{p,m}\right),
\end{eqnarray*}
where for {\it completeness}~\cite{billingsley1995ThirdEdition}, $\F_{-1}:=\sigma(\x_0)$. The idea behind the above definitions is explained in~\cite[Remark~2.1]{DzaWildSub2022}. By construction, $\QkRandom$ and $\Drandom_k$ are $\fqdalgebra$-measurable so that $\E{\QkRandom|\fqdalgebra}=\QkRandom$ almost surely and $\E{\Drandom_k|\fqdalgebra}=\Drandom_k$ almost surely. The sufficient accuracy of the random estimates is formalized as follows.

\begin{definition}
A sequence $\accolade{\Fok,\Fuk}$ of random estimates is called $\beta_f$-probabilistically $\ef$-accurate with respect to the corresponding sequence $\accolade{\Xk,\Dk,\QkRandom,\Drandom_k}$ if the events
\begin{eqnarray*}
J_k&:=&\left\lbrace \mbox{Given}\ \QkRandom, \Drandom_k\ \mbox{and}\ \Xk, \Fok\ \mbox{and}\ \Fuk\ \mbox{are}\ \ef\mbox{-accurate}\ \mbox{estimates of}\ f(\Xk)\ \mbox{and} \right.\\
& & \qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\left. f(\Xk+\Dk\urandom),\ \mbox{respectively, for}\ \Dk \right\rbrace
\end{eqnarray*}
satisfy the condition $\prob{J_k|\fqdalgebra}=\E{\ijk|\fqdalgebra}\geq \beta_f$ almost surely. The estimates $\Fok$ and $\Fuk$ are called ``good'' if $\ijk=1$. Otherwise, they are called ``bad.''
\end{definition}

\begin{assumption}\label{efkfAssump}
For fixed $\ef>0$, {\bl $\gamma>2$, $\nu,\tau\in (0,1)$ satisfying $\frac{\nu}{1-\nu}\geq \frac{2(\tau^{-2}-1)}{\gamma-2}$} and $\beta_f\in ({\bl 1/2},1)$ {\bl satisfying  $\frac{\beta_f}{1-\beta_f}\geq \frac{4\nu}{(1-\nu)(1-\tau^2)}$}, the following hold for the random quantities generated by Algorithm~\ref{algoStoDARS}:
\begin{itemize}
\item[(i)] The sequence $\accolade{\Fok,\Fuk}$ is $\beta_f$-probabilistically $\ef$-accurate.
\item[(ii)] The sequence $\accolade{\Fok,\Fuk}$ satisfies the following $\kappa_f$-variance conditions, each of which holds almost surely:
\[\E{\abs{\Fok-f(\Xk)}^2|\fqdalgebra}\leq \ef^2(1-\beta_f)\Dk^4\quad\mbox{and}\quad \E{\abs{\Fuk-f(\Xk+\Dk\urandom)}^2|\fqdalgebra}\leq \ef^2(1-\beta_f)\Dk^4.\]
\end{itemize}
\end{assumption}

\begin{assumption}\label{boundedFassumpt}{\bl (Inspired by~\cite[Assumption~10.5]{CoScVibook},~\cite[Theorems~3.4 and Section~3.8]{KoLeTo03a})}
The function $f$ is bounded from below; that is, $-\infty<f_{\min}\leq f(\x)$ for some $f_{\min}\in\R$ and all $\x\in{\bl \mathcal{X}}$.
\end{assumption}

\begin{definition}\cite[Definition~1]{blanchet2016convergence}
$\Tepsilon$ is called a \emph{stopping time} with respect to the discrete time process $\accolade{\X_k}_{k\in\N}$ if, for all $k\in\N$, $\accolade{\Tepsilon=k}\in \sigma\left(\X_1,\dots,\X_k \right)$. 
\end{definition}

Consider the discrete time process $\accolade{\left(\Phik,\Dk\right)}_{k\in\N}$, with $\Phik, \Dk\in [0,\infty)$. On the same probability space as $\accolade{\left(\Phik,\Dk\right)}_{k\in\N}$, let us introduce the biased random walk process $\accolade{\Wtildek}_{k\in\N}$ satisfying
\begin{equation}\label{dynamicsWk}
\prob{\Wtildekun=1|\mathcal{H}_k}=q\qquad \mbox{ and }\qquad \prob{\Wtildekun=-1|\mathcal{H}_k}=1-q,
\end{equation}
where $\mathcal{H}_k=\sigma\left( \left(\PhiZero,\Dzero,\WtildeZero\right),\dots,\left(\Phik,\Dk,\Wtildek\right) \right)$ with ${\WtildeZero=1}$, and  $q\in (1/2, 1)$.

Let $\accolade{\Tepsilon}_{\epsilon>0}$ be a family of stopping times with respect to $\accoladekinN{\mathcal{H}_k}$, parameterized by $\epsilon$. In order to derive in~\cite{blanchet2016convergence,dzahini2020expected,DzaWildSub2022,paquette2018stochastic} an upper bound on $\E{\Tepsilon}$,  the following are assumed.

\begin{assumption}{\bl \cite{blanchet2016convergence}}\label{assumptionRenewal}
The discrete time process $\accoladekinN{\left(\Phik,\Dk,\Wtildek\right)}$ satisfies the following:
\begin{itemize}
\item[(i)] There exist $\lambda>0$ and $\dmax=\delta_0 e^{\lambda j_{\max}}$ such that $\Dk\leq \dmax$ for all $k$, where $j_{\max}\in\Z$.
\item[(ii)] For some $j_{\epsilon}\in\Z\cap (-\infty, 0]$, there exists $\depsilon=\delta_0 e^{\lambda j_{\epsilon}}$ such that for all $k$
\begin{equation}\label{dynamicsRenewal} 
\itksup\Dkun\geq \itksup\min\accolade{\Dk e^{\lambda\Wtildekun}, \depsilon}, 
\end{equation}
where $\Wtildekun$ satisfies~\eqref{dynamicsWk}. 
\item[(iii)] There exist a nondecreasing function $h:(0,\infty)\to (0,\infty)$ and a constant $\varrho>0$ such that for all $k$
\[\E{\Phikun-\Phik|\mathcal{H}_k}\itksup\leq-\varrho h\left(\Dk\right)\itksup\quad\mbox{almost surely.}\]
\end{itemize}
\end{assumption}

Consider the discrete time process $\accoladekinN{\left(\Phik,\Dk,\Wtildek\right)}$ defined by the random function~$\Phik$ introduced in Theorem~\ref{zerothOrdTheor}, the stepsize~$\Dk$, and the random variables $\Wtildek:=2\left(\iak\ijk-\frac{1}{2}\right)$, where 
\begin{equation}\label{AkEventDef}
A_k:=\accolade{\alpha_Q\kappa(\pollDrandom_k)\normii{\nabla f(\Xk)}\leq -\sqrt{\frac{n}{p}}\nabla f(\Xk)^{\top}\left(\Ukprandom{\ubar{\hat{\di}}^p_k}\right)}.
\end{equation}

\begin{assumption}\label{kapminAssump}{\bl (\cite[Assumption~(3.12)]{KoLeTo03a}  and~\cite[Assumption~1]{Vicente2013})}
%To SW: above it's really Assumption~"(3.12)"; it's actually an equation, not a standalone assumption
There exists $\kappa_{\min}>0$ such that the realizations of the PSSs used by Algorithm~\ref{algoStoDARS} for subspace polling satisfy $\kappa(\pollD_k)\geq \kappa_{\min}$.
\end{assumption}

\begin{assumption}\label{gradLipAssump}{\bl (Inspired by~\cite[Theorem~2.8]{CoScVibook}, \cite[Theorem~3.3]{KoLeTo03a}, and~\cite[Theorem~1]{Vicente2013}).}
The gradient $\nabla f$ of the objective function is $L_g$-Lipschitz continuous {\bl in an open set containing all the points in the poll sets~$\mathcal{P}_k$}.
%, with $L_g>\kappa_{\min}$.
\end{assumption}

In the following result inspired by~\cite[Lemma~2]{dzahini2020expected}, $\depsilon$ is a constant defined by 
\begin{equation}\label{depsEq}
\depsilon:=\frac{\epsilon}{\xi}\qquad\mbox{with}\qquad\xi>\kappa_{\min}^{-1}\alpha_Q^{-1}\left(L_g\sqrt{\frac{n}{p}}+(\gamma+2)\ef\right)=:\hat{\xi}.
\end{equation}

\begin{lemma}\label{HaarLemma}\cite[Section~2.1]{MeckesElizHaar2019}
Let $\Urandom:=(\UrandomScal_{ij})_{1\leq i,j\leq n}\in \mathbb{O}(n)$ be \emph{Haar}-distributed. Then, the entries of $\Urandom$ are identically distributed. Moreover, $\E{\UrandomScal_{11}}=0$ and $\E{\UrandomScal_{11}^2}=\frac{1}{n}$.
