\begin{lemma}\cite[Theorem~2.7-$(\ell)$]{bhattacharya2007basic}\label{substLemma}
Let $\ubar{\vb}$ and $\Mrandom$ be random maps into $(\mathcal{S}_1, \mathscr{S}_1)$ and $(\mathcal{S}_2, \mathscr{S}_2)$, respectively. Let $\mathcal{F}$ be a $\sigma$-algebra and $\psi$ be a measurable real-valued function on $\left(\mathcal{S}_1\times \mathcal{S}_2, \mathscr{S}_1\bigotimes\mathscr{S}_2\right)$. If $\ubar{\vb}$ is $\mathcal{F}$-measurable, $\sigma(\Mrandom)$ and $\mathcal{F}$ are independent, and $\E{\abs{\psi(\ubar{\vb},\Mrandom)}}<\infty$, then $\E{\psi(\ubar{\vb},\Mrandom)|\mathcal{F}}=\wp(\ubar{\vb})$ almost surely, where $\wp(\vb):=\E{\psi(\vb,\Mrandom)}$ for all $\vb\in\mathcal{S}_1$.
\end{lemma}

