The proof is inspired by that of~\cite[Lemma~2]{dzahini2020expected} using elements derived in~\cite{KoLeTo03a}. Suppose that $\dk\leq \depsilon$, that the event $A_k$ occurs, and that the estimates $\fok$ and $\fuk$ are $\ef$-accurate. Then, assume by way of contradiction that $\fuk-\fok> -\gamma\ef\dk^2$ for all $\ub\in \mathbb{U}_k^n$ of the form $\ub:=\Ukp\di^p$, with $\di^p\in \pollD_k$. Since $A_k$ occurs, then the latter inequality holds in particular for $\ub=\Ukp\hat{\di}^p_k$, with $\hat{\di}^p_k\in\argmax\accolade{-\nabla f(\xk)^{\top}\left(\Qk\di^p\right):\di^p\in\pollD_k}$ satisfying 
\begin{equation}\label{AkRealization}
\alpha_Q\kappa(\pollD_k)\normii{\nabla f(\xk)}\leq -\sqrt{\frac{n}{p}}\nabla f(\xk)^{\top}\left(\Ukp{\hat{\di}^p_k}\right).
\end{equation}

It follows from the $\ef$-accuracy assumption, along with the equality 
\[f(\xk+\dk\ub)-f(\xk)=f(\xk+\dk\ub)-\fuk+(\fuk-\fok)+\fok-f(\xk),\]
that 
\begin{equation}\label{eq39Acc}
f\left(\xk+\dk\Ukp\hat{\di}^p_k\right)-f(\xk)+(\gamma+2)\ef\dk^2\geq 0.
\end{equation}

It follows from the mean value theorem and~\eqref{eq39Acc} that there exists $\mu_k\in[0,1]$ such that 
\begin{equation}\label{eq40MeanVal}
0\leq \dk\nabla f\left(\xk+\mu_k\dk\Ukp\hat{\di}^p_k\right)^{\top}\left(\Ukp{\hat{\di}^p_k}\right)+(\gamma+2)\ef\dk^2.
\end{equation}

Multiplying both sides of~\eqref{eq40MeanVal} by $\frac{1}{\dk}\sqrt{\frac{n}{p}}$ and subtracting $\sqrt{\frac{n}{p}}\nabla f(\xk)^{\top}\left(\Ukp{\hat{\di}^p_k}\right)$ yield
\begin{equation}\label{eq41yield}
-\sqrt{\frac{n}{p}}\nabla f(\xk)^{\top}\left(\Ukp{\hat{\di}^p_k}\right)\leq\sqrt{\frac{n}{p}}\left(\nabla f\left(\xk+\mu_k\dk\Ukp\hat{\di}^p_k\right)- \nabla f(\xk)\right)^{\top}\left(\Ukp{\hat{\di}^p_k}\right)+(\gamma+2)\ef\dk,
\end{equation}

which, combined with~\eqref{AkRealization}, leads to
\begin{equation}\label{eq42Norm}
\begin{split}
\alpha_Q\kappa(\pollD_k)\normii{\nabla f(\xk)}&\leq L_g\sqrt{\frac{n}{p}}\normii{\mu_k\dk\Ukp{\hat{\di}^p_k}}\normii{\Ukp{\hat{\di}^p_k}}+(\gamma+2)\ef\dk \leq \left(L_g\sqrt{\frac{n}{p}}+(\gamma+2)\ef\right)\depsilon,%\\
%&\leq L_g\sqrt{\frac{n}{p}}\dk+(\gamma+2)\ef\dk
\end{split}
\end{equation}

\begin{lemma}\label{dynamicsLemma}
{\bl Let Assumption~\ref{QkHaarAssumpt} hold with $0<\beta_Q<1-\frac{1}{2\beta_f}$ and let Assumptions~\ref{QkHaarAssumpt},~\ref{efkfAssump},~\ref{boundedFassumpt},~\ref{kapminAssump}, and~\ref{gradLipAssump} hold.}
%and all assumptions made in Theorem~\ref{zerothOrdTheor} hold. 
Then Assumption~\ref{assumptionRenewal}-$(ii)$ is satisfied for $\Wtildek:=2\left(\iak\ijk-\frac{1}{2}\right)$, with $\lambda=-\log(\tau)$ and some fixed $q\in (\tilde{\beta}, 1)$, where $\tilde{\beta}=\beta_f(1-\beta_Q)$.
\end{lemma}

\begin{proof}
The result is proved by suitably adapting the proof of~\cite[Lemma~7]{blanchet2016convergence}, as was also done in~\cite[Lemma~3]{dzahini2020expected}, \cite[Lemma~5.3]{DzaWildSub2022} and~\cite[Lemma~4.8]{paquette2018stochastic}. First, observe that~\eqref{dynamicsRenewal} trivially holds when $\itksup=0$. It is shown next that when $\itksup=1$ (which is assumed in the remainder of the proof), then 
\[\Dkun\geq \min\accolade{\depsilon, \min\accolade{\dmax,\tau^{-1}\Dk}\iak\ijk+\tau\Dk\left(1-\iak\ijk\right)}.\] 
Recall that $\dk=\tau^{i_k}\depsilon$ for some integer $i_k$ so that if $\dk>\depsilon$, then $\dk\geq \tau^{-1}\depsilon$, whence $\dkun\geq \tau\dk\geq \depsilon$. Next, assume that $\dk\leq \depsilon$, and observe that $\normii{\nabla f(\xk)}>\eps$ since $\Tepsilon>k$. If $\iak\ijk=1$, it follows from Lemma~\ref{smallLemmaHaar} that the iteration is successful. Consequently, $\dkun=\min\accolade{\tau^{-1}\dk,\dmax}$. But if $\iak\ijk=0$, then it always holds that $\dkun\geq \tau\dk$. The proof is completed by observing that $\prob{\iak\ijk=1|\falgebra}=q$ for some $q\geq\tilde{\beta}$.
\end{proof}

\begin{theorem}\label{zerothOrdTheor}
Let Assumptions~\ref{QkHaarAssumpt},~\ref{efkfAssump} and~\ref{boundedFassumpt} hold. 
%Let $\gamma>2$ and $\nu,\tau\in (0,1)$ satisfying $\frac{\nu}{1-\nu}\geq \frac{2(\tau^{-2}-1)}{\gamma-2}$. Assume that Assumption~\ref{efkfAssump} holds with $\beta_f\in (0,1)$ satisfying  $\frac{\beta_f}{1-\beta_f}\geq \frac{4\nu}{(1-\nu)(1-\tau^2)}$. 
Define $\varrho=\frac{1}{2}\beta_f(1-\nu)(1-\tau^2)$. Then, the random function $\Phik:=\frac{\nu}{\ef}\left(f(\Xk)-f_{\min}\right)+(1-\nu)\Dk^2$ satisfies 
\begin{equation}\label{PhikDynamics}
\E{\Phikun-\Phik|\fqdalgebra}\leq -\varrho\Dk^2 \quad\mbox{almost surely, for all}\ k\in \N, 
\end{equation}
which implies that 
\begin{equation}\label{finiteSeries}
\sum_{k=0}^{\infty}\Dk^2<\infty\quad\mbox{almost surely, whence}\qquad \underset{k\to\infty}{\lim}\Dk=0\quad\mbox{almost surely.}
\end{equation}
\end{theorem}

