\begin{proof}
The proof is similar to that of~\cite[Theorem~2]{dzahini2020expected}, using ideas derived in~\cite{blanchet2016convergence,chen2018stochastic,DzaWildSub2022,paquette2018stochastic}. It is presented here for the sake of clarity and self-containedness. The overall goal is to prove~\eqref{PhikDynamics} since taking the expectation on both its sides leads to~\eqref{finiteSeries} as detailed in~\cite[Theorem~3]{dzahini2020expected}, given that $\Phik>0$ for all~$k\in\N$. The proof considers two cases, {\it good estimates} and {\it bad estimates}, each of which is broken into whether the iteration is successful or not. Throughout, 
\[\mathfrak{S}_k:=\accolade{\mbox{The}\ k\mbox{th iteration is successful}}.\]
{\bf Case~1:} {\it (Good estimates, $\ijk=1$).} The overall goal is to prove that almost surely, 
\begin{equation}\label{treizeEq}
\E{\ijk\left(\Phikun-\Phik\right)|\fqdalgebra}\leq -\beta_f(1-\nu)(1-\tau^2)\Dk^2.
\end{equation}
{{Subcase~$1i$}:} {\it (Successful iteration, $\isk=1$).} A decrease occurs in~$f$ according to~\eqref{decreaseEqu}, and $\Dk$ is updated according to~$\Dkun=\min\accolade{\tau^{-1}\Dk,\dmax}$, whence $\ijk\isk\frac{\nu}{\ef}(f(\Xkun)-f(\Xk))\leq -\ijk\isk\nu(\gamma-2)\Dk^2$ and $\ijk\isk(1-\nu)(\Dkun^2-\Dk^2)\leq \ijk\isk(1-\nu)(\tau^{-2}-1)\Dk^2$, leading to 
\begin{equation}\label{dixseptEq}
\ijk\isk\left(\Phikun-\Phik\right)\leq\ijk\isk\left(-\nu(\gamma-2)+(1-\nu)(\tau^{-2}-1)\right)\Dk^2\leq -\ijk\isk(1-\nu)(1-\tau^2)\Dk^2,
\end{equation}
where the last inequality follows from the above choice of~$\nu$ along with the fact that $1-\tau^2<\tau^{-2}-1$. \\
{{Subcase~$1ii$}:} {\it (Unsuccessful iteration, $\iskc=1$).} The parameter~$\Dk$ is decreased according to $\Dkun=\tau\Dk$, and $f(\Xkun)=f(\Xk)$, whence
\begin{equation}\label{dixhuitEq}
\ijk\iskc\left(\Phikun-\Phik\right)=-\ijk\iskc(1-\nu)(1-\tau^2)\Dk^2.
\end{equation}
Equations~\eqref{dixseptEq} and~\eqref{dixhuitEq} lead to
\begin{equation}\label{vingtEq}
\ijk\left(\Phikun-\Phik\right)\leq -\ijk(1-\nu)(1-\tau^2)\Dk^2.
\end{equation}
Taking the conditional expectation with respect to $\fqdalgebra$ on both sides of~\eqref{vingtEq} and using Assumption~\ref{efkfAssump}-{\it (i)} lead to~\eqref{treizeEq}.
{\bf Case~2:} {\it (Bad estimates, $\ijkc=1$).} Because of bad estimates, an iterate leading to an increase in~$f$ and~$\Dk$, and hence in~$\Phik$, can be accepted by Algorithm~\ref{algoStoDARS}. Such an increase is controlled by using Assumption~\ref{efkfAssump}-{\it (ii)}. The overall goal is to show that almost surely,
\begin{equation}\label{vingtEtUnEq}
\E{\ijkc\left(\Phikun-\Phik\right)|\fqdalgebra}\leq 2\nu(1-\beta_f)\Dk^2.
\end{equation}
{{Subcase~$2i$}:} {\it (Successful iteration, $\isk=1$).} Since $\Fuk-\Fok\leq-\gamma\ef\Dk^2$, then 
\[\ijkc\isk\frac{\nu}{\ef}(f(\Xkun)-f(\Xk))\leq\ijkc\isk\nu\left(-\gamma\Dk^2+\frac{1}{\ef}\left(\abs{f(\Xkun)-\Fuk} + \abs{\Fok-f(\Xk)}\right)\right).\]
Recalling that $\Dkun=\min\accolade{\tau^{-1}\Dk,\dmax}$, and by noticing that $-\nu\gamma+(1-\nu)(\tau^{-2}-1)\leq 0$ due to the above choice of $\nu$, it holds that
% \begin{equation}\label{vingtcinqEq}
% \begin{split}
% \ijkc\isk\left(\Phikun-\Phik\right)&\leq \ijkc\isk\left(\left(-\nu\gamma+(1-\nu)(\tau^{-2}-1) \right)\Dk^2+\frac{\nu}{\ef}\left(\abs{f(\Xkun)-\Fuk} + \abs{\Fok-f(\Xk)}\right) \right)\\
% &\leq \ijkc\isk\left(\frac{\nu}{\ef}\left(\abs{f(\Xkun)-\Fuk} + \abs{\Fok-f(\Xk)}\right) \right)
% \end{split}
% \end{equation}
\begin{equation}\label{vingtcinqEq}
\ijkc\isk\left(\Phikun-\Phik\right)\leq \ijkc\isk\frac{\nu}{\ef}\left(\abs{f(\Xkun)-\Fuk} + \abs{\Fok-f(\Xk)}\right).
\end{equation}
{{Subcase~$2ii$}:} {\it (Unsuccessful iteration, $\iskc=1$).} The upper bound on the change in~$\Phik$ follows from~\eqref{dixhuitEq} by replacing~$\ijk$ with~$\ijkc$. Thus, $\ijkc\iskc\left(\Phikun-\Phik\right)\leq \ijkc\iskc\frac{\nu}{\ef}\left(\abs{f(\Xkun)-\Fuk} + \abs{\Fok-f(\Xk)}\right)$, which, combined with~\eqref{vingtcinqEq}, yields
\begin{equation}\label{vingtseptEq}
\ijkc\left(\Phikun-\Phik\right)\leq \ijkc\frac{\nu}{\ef}\left(\abs{f(\Xkun)-\Fuk} + \abs{\Fok-f(\Xk)}\right).
\end{equation}
Taking the conditional expectation with respect to $\fqdalgebra$ on both sides of~\eqref{vingtseptEq} and applying Lemma~\ref{SDDSlemma1} lead to~\eqref{vingtEtUnEq}. Then, combining~\eqref{treizeEq} and~\eqref{vingtEtUnEq} yields
\[\E{\left(\Phikun-\Phik\right)|\fqdalgebra}\leq (-\beta_f(1-\nu)(1-\tau^2)+2\nu(1-\beta_f))\Dk^2\leq -\varrho\Dk^2, \]
where the last inequality follows from the above choice of $\beta_f$, and the proof is completed.
\end{proof}

