\begin{proposition}\label{decreaseProp1}(Inspired by~\cite[Proposition~1]{dzahini2020expected})
Let $\gamma>2$ be a constant, and let $\fok$ and $\fuk$ be $\ef$-accurate estimates of $f(\xk)$ and $f(\xk+\dk\ub)$, respectively: 
\begin{equation}\label{decreaseEqu}
\mbox{If}\quad \fuk-\fok\leq -\gamma\ef\dk^2,\qquad\mbox{then}\qquad f(\xk+\dk\ub)-f(\xk)\leq -(\gamma-2)\ef\dk^2.
\end{equation}
\end{proposition}

